const cfg = $('Configure Vendors & Drift Baselines').first()?.json || {};
const minScore = Number(cfg.minAcceptableScore ?? 85);
const flagAi = cfg.flagAiSubprocessors !== false;
const alerts = [];

for (const item of $input.all()) {
  const v = item.json;
  if (!v || v.status !== 'audited') continue;

  const score = Number(v.doraNis2Score ?? 0);
  const drift = Boolean(v.trustCenter?.subprocessorDriftDetected);
  const tlsOver200 = Boolean(v.tlsCert?.exceeds200DayLimit);
  const aiList = Array.isArray(v.trustCenter?.aiSubprocessors) ? v.trustCenter.aiSubprocessors : [];
  const flags = Array.isArray(v.riskFlags) ? v.riskFlags : [];

  const triggered = score < minScore || drift || tlsOver200 || (flagAi && aiList.length > 0);
  if (!triggered) continue;

  alerts.push({
    json: {
      domain: v.domain,
      grade: v.grade,
      doraNis2Score: score,
      ballotSc081Status: v.tlsCert?.ballotSc081Status || null,
      tlsValidityDays: v.tlsCert?.validitySpanDays ?? null,
      dmarcPolicy: v.dnsPosture?.dmarcPolicy || null,
      caaPresent: Boolean(v.dnsPosture?.caaPresent),
      trustCenterPlatform: v.trustCenter?.platform || 'None',
      trustCenterUrl: v.trustCenter?.discoveredUrl || null,
      certifications: (v.trustCenter?.certifications || []).join(', '),
      aiSubprocessors: aiList.join(', '),
      subprocessorDriftDetected: drift,
      subprocessorHashSha256: v.trustCenter?.subprocessorHashSha256 || null,
      riskFlags: flags.join(', '),
      alertSummary: `${v.domain} -> Grade ${v.grade} (${score}/100) | TLS=${v.tlsCert?.ballotSc081Status || 'n/a'} | Drift=${drift} | AI=[${aiList.join(', ') || 'none'}]`,
      auditedAt: v.auditedAt || null
    }
  });
}

return alerts;
